/// Checks whether `sub` matches `main` starting at index `start`.
/// It is assumed that `start + sub.len()` does not exceed `main.len()`.
fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Compare each element of `sub` with the corresponding element of `main`
    for (offset, &sub_val) in sub.iter().enumerate() {
        if main[start + offset] != sub_val {
            return false;
        }
    }
    true
}

/// Returns true if and only if `sub` appears as a contiguous subarray of `main`.
/// The empty `sub` always qualifies (returns true). If `sub` is longer than `main`,
/// returns false.
fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // An empty subarray is always found
    if sub.is_empty() {
        return true;
    }
    // If sub is longer than main, it can't be contained
    if sub.len() > main.len() {
        return false;
    }
    // Try every possible starting position
    let last_start = main.len() - sub.len();
    for start in 0..=last_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}

